#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// The mirror rate-limits: on any given run, one package per run comes
// back with HTTP 429 and which package is limited moves with the run
// number. A 429 is a transient "slow down" signal, so we honor the
// retry guidance (back off and try again) instead of failing the check.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// Talk to the mirror the way a client would over HTTP.
//
// 200 -> the package metadata.
// 404 -> the version is not on the mirror (not recoverable by retrying).
// 429 -> the mirror is busy and asks us to retry; which package is
//        limited rotates with the attempt number, so backing off and
//        retrying clears it.
function httpGet(name) {
  const limited = deps[run % deps.length];
  if (name === limited) return { status: 429 };
  try {
    const meta = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    return { status: 200, body: meta };
  } catch (err) {
    return { status: 404 };
  }
}

async function fetchMeta(name, maxAttempts = 5) {
  let delay = 1000; // retry-after, in ms; doubles each retry
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const res = httpGet(name);
    if (res.status === 200) return res.body;
    if (res.status === 429) {
      console.error("429 Too Many Requests: " + name +
        " (registry mirror busy, retry in a few seconds)");
      if (attempt === maxAttempts) return null;
      console.error("retrying " + name + " in " + delay + "ms");
      await sleep(delay);
      delay *= 2;
      continue;
    }
    // 404 (or anything else) is not a rate limit; retrying won't help.
    return null;
  }
  return null;
}

(async () => {
  let failed = false;
  for (const name of deps) {
    const meta = await fetchMeta(name);
    if (!meta) {
      console.error("ERR! " + name + "@" + pkg.dependencies[name] +
        " could not be verified against the mirror");
      failed = true;
      continue;
    }
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
})();

