process.chdir(root);

const RETRY_DELAY_MS = 500; // back-off a 429 tells us to take
const MAX_ATTEMPTS_PER_PKG = 6;

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

function sleep(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* spin */ }
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// Talk to the mirror the way a client would over HTTP.
//
// 200 -> the package metadata.
// 404 -> the version is not on the mirror (retrying won't help).
// 429 -> the mirror is busy; back off and retry.
//
// The mirror's per-run throttle: on run number `run`, one package is
// limited on its first request; the one that is limited rotates with the
// run. `limited` records which package was limited this run; once we have
// backed off and retried it, the mirror has cooled down and serves it.
const limited = deps[run % deps.length];
const cooledDown = new Set();

function httpGet(name) {
  if (name === limited && !cooledDown.has(name)) {
    return { status: 429 };
  }
  try {
    const body = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    return { status: 200, body };
  } catch (err) {
    return { status: 404 };
  }
}

function fetchMeta(name) {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS_PER_PKG; attempt++) {
    const res = httpGet(name);
    if (res.status === 200) return { status: 200, body: res.body };
    if (res.status === 429) {
      console.error("429 Too Many Requests: " + name +
        " (registry mirror busy, retrying in a few seconds)");
      if (attempt === MAX_ATTEMPTS_PER_PKG) {
        return { status: 429 };
      }
      cooledDown.add(name); // the backoff lets the mirror cool down
      sleep(RETRY_DELAY_MS);
      continue;
    }
    // 404 (or any other status) is not a rate limit; don't retry it.
    return res;
  }
  return { status: 599 };
}

let failed = false;
for (const name of deps) {
  const res = fetchMeta(name);
  if (res.status === 200) {
    if (res.body.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  } else {
    console.error("ERR! " + name + "@" + pkg.dependencies[name] +
      " could not be verified against the mirror (HTTP " + res.status + ")");
    failed = true;
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");
